ruleToc.chapterList:
@js:
var prefix = decodeURIComponent(String(baseUrl).replace(/^https?:\/\/[^/]+/, "").split(/[?#]/)[0]).replace(/\/$/, "") + "/";
var links = java.getElements("#mw-content-text .mw-parser-output a[href]");
var chapters = []; var seen = {};
for (var i = 0; i < links.size(); i++) {
  var item = links.get(i);
  var path = decodeURIComponent(String(item.attr("href")).split(/[?#]/)[0]);
  var tail = path.indexOf(prefix) === 0 ? path.substring(prefix.length) : "";
  if (/^第[^/]+[回章卷節节]$/.test(tail) && !seen[path]) { chapters.push(item); seen[path] = true; }
}
chapters;

ruleContent.content:
@js:
var nodes = java.getElements("#mw-content-text .mw-parser-output");
if (nodes.size() === 0) "";
else {
  var body = nodes.get(0).clone();
  body.select("#headerContainer,.ws-noexport,.noprint,.mw-editsection,script,style,noscript").remove();
  body.html();
}

ruleSearch.bookList:
@js:
var match = /[?&]reader_query=([^&]*)/.exec(String(baseUrl));
var key = match ? decodeURIComponent(match[1].replace(/\+/g, " ")) : "";
key = String(java.t2s(key)).trim();
var rows = java.getElements("div.sonspic:has(.cont > p > a[href~=/guwen/book_[0-9a-f]+\\.aspx$])");
var found = [];
for (var i = 0; i < rows.size(); i++) {
  var row = rows.get(i); var name = String(row.select(".cont > p > a[href*=/guwen/book_]").first().text());
  if (key === "" || String(java.t2s(name)).indexOf(key) >= 0) found.push(row);
}
found;
